"""Calculates the interpolated result intermediate between two slices:
         result = (1.-f)*S1 + f*S2"""
def weightSlice(S1: Any, S2: Any, f: Any) -> object {
    ns = len(S1);
    rt = [];
    for i in range(0, ns) {
        if ((S1[i][0] < 0) or (S2[i][0] < 0)) {
            rt.append((-32767.0, -32767.0, -32767.0));
        } else {
            r0 = ((1.0 - f) * S1[i][0]) + (f * S2[i][0]);
            r1 = ((1.0 - f) * S1[i][1]) + (f * S2[i][1]);
            r2 = ((1.0 - f) * S1[i][2]) + (f * S2[i][2]);
            rt.append((r0, r1, r2));
        }
    }
    return rt;
}

"""Rounds an integer value up to a multiple specified."""
def _round_up_to_multiple(value: Any, multiple: Any) -> object {
    mod = value % multiple;
    if (mod == 0) {
        return value;
    }
    return ((value - mod) + multiple);
}

"""Standard revcomp
    """
def revcomp(seq: Any, ttable: Any = str.maketrans('ATCG', 'TAGC')) -> object {
    return seq.translate(ttable)[::-1];
}

"""Return a boolean indicating whether given items are in sorted order.
    Running time: O(n) because we are using a loop to traverse through each item in the list
    Memory usage: O(1) because we aren't creating any additional data structures in the function"""
def is_sorted(items: Any) -> object {
    for i in range((len(items) - 1)) {
        current = items[i];
        nextItem = items[(i + 1)];
        if (nextItem < current) {
            return False;
        }
    }
    return True;
}

"""
    Return a variant dictionary
    """
def get_vep_variant(
    chrom: Any = '1',
    pos: Any = '1',
    ref: Any = 'A',
    alt: Any = 'G',
    annotation: Any = "ADK"
) -> object {
    variant_id = '_'.join([chrom, pos, ref, alt]);
    variant = {
        "CHROM": chrom,
        "POS": pos,
        "INFO": "Annotation={0}".format(annotation),
        'vep_info': {'A': [{"Gene": annotation, "Consequence": 'transcript_ablation'}]},
        "variant_id": variant_id
    };
    return variant;
}

